bool RowFromJsonTolerant( RowBuilder & builder, const char * text, int64_t bytes, TableReport * report )
{
    Row * root = builder.GetRoot();
    if ( root == NULL ) { if ( report != NULL ) { report->malformed = true; } return false; } // locked, or the root allocation failed
    TableReport ignored;
    TableReport * to = report != NULL ? report : &ignored;
    const bool malformed_before = to->malformed;
    to->malformed = false;
    const bool ok = TableJsonReadGraph( builder.main, root, RowTableType(), text, bytes, to );
    if ( !ok || to->malformed ) { to->malformed = true; RowTableType()->reset( root ); return false; } // damage discards the whole load (§4)
    to->malformed = malformed_before;
    return true;
}

bool RowFromJson( RowBuilder & builder, const char * text, int64_t bytes, TableReport * report )
{
    Row * root = builder.GetRoot();
    if ( root == NULL ) { if ( report != NULL ) { *report = TableReport(); } return false; } // locked: the report stays empty
    TableReport read;
    bool ok = TableJsonReadGraph( builder.main, root, RowTableType(), text, bytes, &read );
    if ( !ok || read.clamped != 0 || read.kind_mismatch != 0 || read.malformed )
    {
        if ( !ok || read.malformed ) { read.refuse_reason = TableRefuseReason::malformed; }
        else if ( read.clamped != 0 ) { read.refuse_reason = TableRefuseReason::clamped; }
        else { read.refuse_reason = TableRefuseReason::kind_mismatch; }
        RowTableType()->reset( root );
        if ( report != NULL ) { *report = read; }
        return false;
    }
    read.refuse_reason = TableRefuseReason::ok;
    if ( report != NULL ) { *report = read; }
    return true;
}

int64_t RowToJsonMeasure( const Row * root, TableAllocator allocator )
{
    return TableJsonWriteGraph( root, RowTableType(), NULL, 0, allocator );
}

int64_t RowToJson( const Row * root, char * buffer, int64_t capacity, TableAllocator allocator )
{
    return TableJsonWriteGraph( root, RowTableType(), buffer, capacity, allocator );
}

